function b64ToBytes(b64){b64=b64.replace(/-/g,'+').replace(/_/g,'/');while(b64.length%4)b64+='=';const bin=atob(b64);return Uint8Array.from(bin,c=>c.charCodeAt(0));}
async function decryptPayload(pack){validateSecureEnvelope(pack);const p=pack.payload;if(p.mode==='plain-b64')throw new Error('Nešifrovaný BASE64 fallback není v provozní verzi povolen.');if(!PRIVATE_KEY)throw new Error('Chybí soukromý klíč verifieru.');const priv=await crypto.subtle.importKey('jwk',PRIVATE_KEY,{name:'RSA-OAEP',hash:'SHA-256'},false,['decrypt']);const raw=await crypto.subtle.decrypt({name:'RSA-OAEP'},priv,b64ToBytes(p.key));const aes=await crypto.subtle.importKey('raw',raw,{name:'AES-GCM'},false,['decrypt']);const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:b64ToBytes(p.iv)},aes,b64ToBytes(p.data));e3Require(plain.byteLength<=E3_MAX_TXT,'schema.size','Dešifrovaný payload je příliš velký.');return e3Json(new TextDecoder('utf-8',{fatal:true}).decode(plain));}
