function renderSecuritySignals(){const box=$('securitySignals');if(!box)return;const ok=resolvedResults();if(!ok.length){box.innerHTML='<div class="muted">Zatím nejsou načtené žádné opravené výsledky.</div>';return;}const info=duplicateInfo();const allRows=[];ok.forEach(r=>{securitySignalsFor(r,info).forEach(sig=>allRows.push({r,sig}));});const hard=allRows.filter(x=>x.sig.sev==='hard').length;const soft=allRows.filter(x=>x.sig.sev==='soft').length;const audit=allRows.filter(x=>x.sig.sev==='info').length;const clear=ok.filter(r=>securitySignalsFor(r,info).every(s=>s.sev==='info'||['external-anchors-unverified','unverified-telemetry'].includes(s.code))).length;const q=VERIFIER_SECURITY_QUERY;const rows=q?allRows.filter(function(x){return [displayStudent(x.r),x.r.student,x.r.formIdentity,x.r.attemptId,x.r.code,x.sig.label,x.sig.detail].some(function(v){return String(v||'').toLocaleLowerCase('cs').includes(q);});}):allRows.slice();let html='<div class="signal-grid"><div class="signal-card '+(hard?'':'ok')+'"><b>'+hard+'</b><span>tvrdších signálů</span><div class="signal-note">dlouhý odchod, opakované opuštění, reload, pagehide, zámek</div></div><div class="signal-card'+(soft?'':' ok')+'"><b>'+soft+'</b><span>měkkých signálů</span><div class="signal-note">krátké přepnutí, split-window nebo metadata Google Forms — vždy posuď v kontextu</div></div><div class="signal-card ok"><b>'+audit+'</b><span>auditních informací</span><div class="signal-note">např. správné recovery odemčení; samo o sobě nezvyšuje počet problémů</div></div><div class="signal-card"><b>'+clear+'</b><span>výsledků bez dalších hlášených signálů</span></div></div>';html+=trustNoticeHtml();html+='<div class="archive-note" style="margin-top:8px"><b>Toto není automatický důkaz podvodu.</b> Správný Classroom Recovery Code se eviduje jako auditní informace. Posuď podle kontextu: měkké signály vznikají na mobilech běžně (notifikace, příchozí hovor, systémová lišta, uspání displeje). Tvrdší signály si zaslouží pozornost, ale ani ty nejsou rozsudek — porovnej je s časem, počtem a prací studenta.</div>';if(q)html+='<div class="v2-filter-note">Filtr: <b>'+esc(q)+'</b> · zobrazeno '+rows.length+' z '+allRows.length+' záznamů.</div>';if(!allRows.length){box.innerHTML=html+'<div class="warn">Klient nehlásí další události. Jejich absence neprokazuje původ ani čistý průběh.</div>';return;}if(!rows.length){box.innerHTML=html+'<div class="muted">Filtru neodpovídá žádný bezpečnostní ani auditní záznam.</div>';return;}const rank={hard:0,soft:1,info:2};rows.sort((a,b)=>(rank[a.sig.sev]??3)-(rank[b.sig.sev]??3)||String(displayStudent(a.r)).localeCompare(String(displayStudent(b.r)),'cs'));html+='<div style="overflow:auto"><table class="tbl"><tr><th>Student</th><th>ID pokusu</th><th>Kategorie</th><th>Záznam</th><th>Detail</th></tr>'+rows.map(x=>{const isHard=x.sig.sev==='hard',isInfo=x.sig.sev==='info';const badge=isInfo?'audit':(isHard?'tvrdší':'měkký');const cls=isInfo?'sev-soft':(isHard?'sev-hard':'sev-soft');return '<tr class="'+(isHard?'result-row-warn':'')+'"><td>'+esc(displayStudent(x.r))+'</td><td>'+esc(x.r.attemptId||'—')+'</td><td><span class="sev-badge '+cls+'">'+badge+'</span></td><td>'+esc(x.sig.label)+'</td><td>'+esc(x.sig.detail||'—')+'</td></tr>';}).join('')+'</table></div>';box.innerHTML=html;}
