function prtCss(){return '@media print{.no-print{display:none!important}.variant{page-break-after:always}}'+'body{font-family:Georgia,serif;color:#000;background:#fff;margin:0;line-height:1.5}'+'.toolbar{position:sticky;top:0;background:#1d4ed8;color:#fff;padding:10px 16px;display:flex;gap:10px;align-items:center;flex-wrap:wrap}'+'.toolbar button{background:#fff;color:#1d4ed8;border:0;border-radius:8px;padding:9px 14px;font-weight:800;cursor:pointer;font-size:14px}'+'.page{max-width:780px;margin:0 auto;padding:22px}'+'.phead{position:relative;min-height:54px;padding-right:118px;border-bottom:2px solid #000;padding-bottom:10px;margin-bottom:14px}.school-logo{position:absolute;right:0;top:0;max-width:105px;max-height:52px;object-fit:contain}'+'.ptitle{font-size:20px;font-weight:800}.pmeta{font-size:12px;color:#333;margin:4px 0}'+'.pname{margin-top:8px;font-size:14px}'+'.vlabel{font-weight:800;background:#eee;padding:4px 8px;border-radius:6px;display:inline-block;margin-bottom:8px}'+'.ex{margin:14px 0;border-top:1px solid #999;padding-top:8px}'+'.exh{font-size:15px}.instr{font-size:12px;font-style:italic;color:#444;margin:2px 0 8px}'+'.q{margin:9px 0}.qh{margin-bottom:4px}'+'.opts{margin:4px 0 4px 18px}.opts li{margin:2px 0}.keyopt{font-weight:800}'+'.tf{margin:4px 0;font-weight:600}'+'.src{background:#f4f6fb;border-left:3px solid #1d4ed8;padding:7px 10px;margin:6px 0;font-size:13px}'+'.ans-line{border-bottom:1px solid #000;height:24px;margin:8px 0}'+'.num-line{display:flex;align-items:center;gap:6px;margin:5px 0}'+'.ul{display:inline-block;border-bottom:1px solid #000;min-width:150px;height:16px}.ul-sm{min-width:60px}.ul-lg{min-width:220px}'+'.match{display:flex;gap:26px;margin:6px 0}.match-col{flex:1}'+'.muted{color:#666;font-size:12px}'+'.key-ans{background:#eef6ff;padding:5px 8px;border-radius:6px;margin-top:5px;font-size:13px}'+'.key-expl{font-size:12px;color:#333;margin-top:3px}';}
function prtNonce(){var a=new Uint8Array(16);crypto.getRandomValues(a);return Array.prototype.map.call(a,function(x){return x.toString(16).padStart(2,'0');}).join('');}
