function openPrint(withKey){var nonce=prtNonce();var html=buildPrintableHtml(withKey,nonce);var w=null;try{w=window.open('','_blank');}catch(e){w=null;}if(w&&w.document){try{w.opener=null;}catch(_e){}w.document.title='Tisk testu';w.document.documentElement.style.height='100%';w.document.body.style.cssText='margin:0;height:100%;overflow:hidden';var f=w.document.createElement('iframe');f.setAttribute('sandbox','allow-scripts allow-modals');f.setAttribute('title','Izolovaný tiskový náhled');f.style.cssText='border:0;width:100%;height:100%';f.srcdoc=html;w.document.body.appendChild(f);}else{downloadText(html,(withKey?'klic_':'arch_')+safeFileName(CONFIG.nazev||'test')+'_'+CONFIG.testId+'.html','text/html;charset=utf-8');}}

